class Solution {
    public long wonderfulSubstrings(String word){
        long[] frequency=new long[1<<10];
        frequency[0]=1;
        long answer=0;
        int mask=0;
        for(char letter:word.toCharArray()){
            mask^=1<<(letter-'a');
            answer+=frequency[mask];
            for(int bit=0;bit<10;bit++)answer+=frequency[mask^(1<<bit)];
            frequency[mask]++;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun wonderfulSubstrings(word:String):Long{
        val frequency=LongArray(1 shl 10);
        frequency[0]=1;
        var answer=0L;
        var mask=0;
        for(letter in word){
            mask=mask xor (1 shl (letter-'a'));
            answer+=frequency[mask];
            for(bit in 0 until 10)answer+=frequency[mask xor (1 shl bit)];
            frequency[mask]++
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: long long wonderfulSubstrings(string word){
        long long frequency[1<<10]={
            1
        },answer=0;
        int mask=0;
        for(char letter:word){
            mask^=1<<(letter-'a');
            answer+=frequency[mask];
            for(int bit=0;bit<10;++bit)answer+=frequency[mask^(1<<bit)];
            ++frequency[mask];
        }
        return answer;
    }
};
